argv:
$ErrorActionPreference='Stop'
$sw=[Diagnostics.Stopwatch]::StartNew();$marks=[ordered]@{}
function Mark([string]$n){$marks[$n]=[math]::Round($sw.Elapsed.TotalSeconds,2)}
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W32PasteFast {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr hWnd, StringBuilder sb, int max);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@
# Close any lingering common Open dialog.
$script:dlg=[IntPtr]::Zero
$cb=[W32PasteFast+EnumWindowsProc]{
 param($h,$l)
 $tsb=New-Object System.Text.StringBuilder 128;$csb=New-Object System.Text.StringBuilder 64
 [void][W32PasteFast]::GetWindowText($h,$tsb,$tsb.Capacity);[void][W32PasteFast]::GetClassName($h,$csb,$csb.Capacity)
 if($tsb.ToString() -eq '開啟' -and $csb.ToString() -eq '#32770'){$script:dlg=$h;return $false}
 return $true
}
[W32PasteFast]::EnumWindows($cb,[IntPtr]::Zero)|Out-Null
if($script:dlg -ne [IntPtr]::Zero){[W32PasteFast]::SetForegroundWindow($script:dlg)|Out-Null;[System.Windows.Forms.SendKeys]::SendWait('{ESC}');Start-Sleep -Seconds 1}
$img=Get-ChildItem -LiteralPath (Join-Path $env:USERPROFILE 'Downloads') -File | Where-Object {$_.Extension -match '(?i)^\.(png|jpg|jpeg|webp)$'} | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if($null -eq $img){throw 'No image found'}
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible'}
[W32PasteFast]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null;Start-Sleep -Milliseconds 300
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$composer=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and [string]$e.Current.Name -like '文字欄位*新貼文*'){$composer=$e;break}
}
if($null -eq $composer){throw 'Threads composer not found'}
$composer.SetFocus()
$bitmap=[System.Drawing.Image]::FromFile($img.FullName)
try{
 [System.Windows.Forms.Clipboard]::SetImage($bitmap);Start-Sleep -Milliseconds 300
 [System.Windows.Forms.SendKeys]::SendWait('^v')
}finally{$bitmap.Dispose()}
Start-Sleep -Seconds 7;Mark 'image_pasted'

$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$publish=$null
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq '發佈' -and $e.Current.IsEnabled){
  $r=$e.Current.BoundingRectangle;if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 450){$publish=$e;break}
 }
}
if($null -eq $publish){throw 'Threads publish button not found'}
$publish.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();Mark 'publish_invoked'
Start-Sleep -Seconds 8
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$needle=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('56ys5LqM6LyqIEFnZW50T1MgR1VJIERlbW8='))
$found=$false
for($i=0;$i -lt $all.Count;$i++){if(([string]$all.Item($i).Current.Name) -like ('*'+$needle+'*')){$found=$true;break}}
Mark 'verified'
[pscustomobject]@{verified=$found;image=$img.FullName;bytes=$img.Length;marks=$marks;elapsed_seconds=[math]::Round($sw.Elapsed.TotalSeconds,2)}|ConvertTo-Json -Depth 5 -Compress
